src = open("carbon_market/signal_ingest.py", encoding="utf-8").read()
tree = ast.parse(src)
assigned = set()
for node in ast.walk(tree):
    if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)):
        assigned.add(node.name)
    elif isinstance(node, ast.Assign):
        for t in node.targets:
            if isinstance(t, ast.Name): assigned.add(t.id)
    elif isinstance(node, ast.AnnAssign) and isinstance(node.target, ast.Name):
        assigned.add(node.target.id)
used = {n.id for n in ast.walk(tree) if isinstance(n, ast.Name)
        and isinstance(n.ctx, ast.Load)}
unused = sorted(n for n in assigned if n.isupper() or n.startswith("_"))
for n in unused:
    if n not in used and n not in ("__name__",):
        print("possibly unused:", n)
